#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────


run_wizard() {

TOTAL_STAGES=7

# Walks you through setting up the release key (docs/release-signing.md): the steps only
# you can do, on your own PC. Run it from Git Bash in a checkout of this repository:
#   bash scripts/release-signing-wizard.sh
ROOT=$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)
cd "$ROOT"
export GH_REPO=MatiasCiccone/t3wow
# Remembers where the key went, between runs. Never the key itself.
ENV_FILE="$HOME/.t3wow-release-signing.env"
KEY_RS=companion/src/updater/release_key.rs
PR_URL=""

# Paths go through node, which takes both the C:\... and the /c/... forms.
key_exists() { node -e 'process.exit(require("fs").existsSync(process.argv[1]) ? 0 : 1)' "$1"; }
read_key() { node -e 'process.stdout.write(require("fs").readFileSync(process.argv[1], "utf8"))' "$T3WOW_RELEASE_KEY_PATH"; }
key_is_set() { ! grep -q 'RELEASE_PUBLIC_KEY: \[u8; 32\] = \[0; 32\];' "$KEY_RS"; }
check_key() { T3WOW_SIGNING_KEY="$(read_key)" node scripts/sign-release.mjs --check; }
public_key_hex() {
  node --input-type=module -e 'import { readFileSync } from "node:fs"; import { embeddedPublicKey } from "./scripts/release-key.mjs"; console.log(embeddedPublicKey(readFileSync(process.argv[1], "utf8")).toString("hex"));' "$KEY_RS"
}

banner "T3 WoW release signing"

# ──────────────────────────────────────────────────────────────────────────
stage "Check the tools"
say "This makes the release key: every t3wow.exe update gets signed with it in CI,"
say "and companions built with its public half refuse updates without that signature."
note "Why and how: docs/release-signing.md"
for tool in node git gh; do
  command -v "$tool" >/dev/null 2>&1 || { warn "$tool isn't installed or isn't on PATH."; exit 1; }
done
if ! gh auth status >/dev/null 2>&1; then
  warn "gh isn't signed in: run gh auth login, then this wizard again."
  exit 1
fi
if key_is_set; then
  note "$KEY_RS already holds a key: the stages that make one check it instead."
elif [[ -n "$(git status --porcelain)" ]]; then
  warn "This checkout has uncommitted changes. Commit or set them aside first, so the"
  warn "key's commit holds only the key."
  exit 1
fi
say "${GREEN}✓${RESET} node, git and gh are ready. Repository $GH_REPO, branch $(git branch --show-current)."
pause

# ──────────────────────────────────────────────────────────────────────────
stage "Make the key pair"
say "The private key goes in a file outside this repository, on this PC only."
say "The public key goes into $KEY_RS, to be committed."
if [[ -n "${USERPROFILE:-}" ]]; then DEFAULT_KEY="$USERPROFILE\\keys\\t3wow-release-key.pem"; else DEFAULT_KEY="$HOME/keys/t3wow-release-key.pem"; fi
note "Leave it empty for $DEFAULT_KEY"
ask T3WOW_RELEASE_KEY_PATH "Private key file:" || true
T3WOW_RELEASE_KEY_PATH="${T3WOW_RELEASE_KEY_PATH:-$DEFAULT_KEY}"
write_env T3WOW_RELEASE_KEY_PATH "$T3WOW_RELEASE_KEY_PATH"
if key_exists "$T3WOW_RELEASE_KEY_PATH"; then
  if key_is_set && check_key >/dev/null 2>&1; then
    say "${GREEN}✓${RESET} Already made: that file matches the key in $KEY_RS."
  else
    warn "$T3WOW_RELEASE_KEY_PATH exists but doesn't match $KEY_RS."
    say "Run the wizard again with another path, or see docs/release-signing.md."
    exit 1
  fi
elif key_is_set; then
  warn "$KEY_RS already holds a key, but $T3WOW_RELEASE_KEY_PATH doesn't exist."
  say "Run the wizard again with that key's file. If the key is lost, see"
  say "\"Losing or replacing the key\" in docs/release-signing.md."
  exit 1
else
  node -e 'const p = require("path"); require("fs").mkdirSync(p.dirname(p.resolve(process.argv[1])), { recursive: true });' "$T3WOW_RELEASE_KEY_PATH"
  node scripts/gen-signing-key.mjs "$T3WOW_RELEASE_KEY_PATH"
fi
pause

# ──────────────────────────────────────────────────────────────────────────
stage "Back up the private key"
PUBLIC_HEX=$(public_key_hex)
say "Lose this file and no later release can update existing companions: everyone"
say "would have to download t3wow.exe again by hand. Leak it and someone else could"
say "sign an update your companions install."
step "Copy $T3WOW_RELEASE_KEY_PATH to two places off this PC, for example:"
note "    your password manager, as an attachment on an entry named \"t3wow release key\""
note "    a USB stick or an encrypted archive kept offline"
step "Note the public key with it, to tell this key apart later:"
note "    $PUBLIC_HEX"
step "Keep it out of email, chat, plain cloud-synced folders and any repository."
until confirm "Is the key backed up somewhere off this PC?"; do
  warn "Back it up before going on: the next stages make releases depend on it."
done

# ──────────────────────────────────────────────────────────────────────────
stage "Check it locally"
say "Checking the private key against $KEY_RS, as the Release workflow will."
check_key || { warn "The key check failed: see the message above."; exit 1; }
node --test tests/release-signing.test.js >/dev/null \
  || { warn "The release signing tests fail: run node --test tests/release-signing.test.js."; exit 1; }
say "${GREEN}✓${RESET} The release signing tests pass."
if command -v cargo >/dev/null 2>&1; then
  say "Building the companion's tests to check it has the key (a minute or two)..."
  cargo test --quiet --manifest-path companion/Cargo.toml -- --ignored the_release_public_key_is_set \
    || { warn "The companion doesn't have the key: see the output above."; exit 1; }
  say "${GREEN}✓${RESET} The companion has the key."
else
  note "cargo isn't installed: CI runs the companion's tests on the pull request."
fi
pause

# ──────────────────────────────────────────────────────────────────────────
stage "Open a pull request with the public key"
say "The public key isn't secret. It's committed, so every build embeds it."
if git diff --quiet HEAD -- "$KEY_RS"; then
  say "${GREEN}✓${RESET} $KEY_RS is already committed on this branch."
  PR_URL=$(gh pr view --json url --jq .url 2>/dev/null || true)
elif confirm "Commit $KEY_RS on a new branch, push it and open a pull request to main?"; then
  if [[ "$(git branch --show-current)" == main ]]; then git switch -c release-public-key; fi
  git commit --quiet -m "feat(companion): updates install only when signed with the project's release key" -- "$KEY_RS"
  git push --quiet -u origin HEAD
  PR_URL=$(gh pr create --base main --fill --body "Puts the release key's public half in companion/src/updater/release_key.rs (made with scripts/gen-signing-key.mjs). From the next release on, companions refuse an update whose t3wow.exe.sha256 isn't signed with it. See docs/release-signing.md.")
  say "${GREEN}✓${RESET} Opened $PR_URL"
else
  SKIPPED+=("commit $KEY_RS and open a pull request to main")
fi
pause

# ──────────────────────────────────────────────────────────────────────────
stage "Add the private key as a GitHub secret"
say "The Release workflow signs with the T3WOW_SIGNING_KEY secret of $GH_REPO."
note "Until the pull request merges, a pushed tag stops at the Release key step (the"
note "secret without the key), so merge before tagging. Nothing gets published that way."
if confirm "Set T3WOW_SIGNING_KEY from $T3WOW_RELEASE_KEY_PATH now?"; then
  set_secret T3WOW_SIGNING_KEY "$(read_key)"
else
  SKIPPED+=("gh secret set T3WOW_SIGNING_KEY --repo $GH_REPO < <the key file>")
fi
step "It's listed under Repository secrets (GitHub never shows the value again):"
open_url "https://github.com/$GH_REPO/settings/secrets/actions"
pause

# ──────────────────────────────────────────────────────────────────────────
stage "Merge, then release"
open_url "${PR_URL:-https://github.com/$GH_REPO/pulls}"
step "Merge the pull request once CI passes."
step "Release as usual: the same version in the three files, then push the tag."
step "In the Release run, the Release key step says the key matches the companion's."
step "The release on t3wow-releases lists t3wow.exe.sha256.sig."
note "Companions up to 0.5.0 check only the SHA-256, so they update to it. Every"
note "companion from that release on requires the signature."
step "Once a backup is known to open, you can delete the key file from this PC."
pause

finish
}

run_wizard "$@"; exit
